}
transformed parameters {
  vector[K] theta;
  theta <- z ./ sqrt(u / nu);
}
model {
  z ~ normal(0,1);
  u ~ chi_square(nu);
  # implies theta ~ multi_normal_t(zero, I);

}
generated quantities {
